class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        hi = min(coins) * k
        cap = hi + 1  # any lcm >= cap contributes floor(X/lcm)=0 for X<=hi

        # Build signed lcm list over nonempty subsets, dropping those >= cap
        terms = []  # (lcm, sign)
        # lcms[mask] stored; capped at cap (value cap means "too large")
        lcms = [1] * (1 << n)
        for mask in range(1, 1 << n):
            low = mask & (-mask)
            idx = low.bit_length() - 1
            prev = lcms[mask ^ low]
            if prev >= cap:
                lcms[mask] = cap
                continue
            c = coins[idx]
            l = prev * c // gcd(prev, c)
            lcms[mask] = l if l < cap else cap
            if lcms[mask] < cap:
                sign = 1 if bin(mask).count("1") % 2 == 1 else -1
                terms.append((lcms[mask], sign))

        def count(X: int) -> int:
            total = 0
            for l, s in terms:
                if l <= X:
                    total += s * (X // l)
            return total

        lo, hi_b = 1, hi
        while lo < hi_b:
            mid = (lo + hi_b) // 2
            if count(mid) >= k:
                hi_b = mid
            else:
                lo = mid + 1
        return lo
