class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        hi = k * min(coins)
        CAP = hi + 1  # any lcm above this contributes 0 to counts

        # Precompute signed subset lcms (capped)
        terms = []  # (sign, lcm)
        for mask in range(1, 1 << n):
            l = 1
            bits = 0
            over = False
            for i in range(n):
                if mask >> i & 1:
                    bits += 1
                    if not over:
                        l = l * coins[i] // gcd(l, coins[i])
                        if l > CAP:
                            over = True
            if over:
                continue
            sign = 1 if bits % 2 == 1 else -1
            terms.append((sign, l))

        def count(x):
            total = 0
            for sign, l in terms:
                total += sign * (x // l)
            return total

        lo, hi_b = 1, hi
        while lo < hi_b:
            mid = (lo + hi_b) // 2
            if count(mid) >= k:
                hi_b = mid
            else:
                lo = mid + 1
        return lo

