def gen(draw):
    n = draw(st.integers(1, 15))
    coins = draw(st.lists(st.integers(1, 25), min_size=n, max_size=n, unique=True))
    # Edge cases: k=1, small k, and moderately larger k (kept small for brute force).
    k = draw(st.one_of(st.just(1), st.integers(1, 60)))
    return f"{json.dumps(coins)}\n{k}\n"

def _parse(inp):
    lines = inp.strip().split("\n")
    coins = json.loads(lines[0])
    k = json.loads(lines[1])
    return coins, k

def validate(inp: str) -> bool:
    try:
        lines = [l for l in inp.strip().split("\n")]
        if len(lines) != 2:
            return False
        coins = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(coins, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    if not (1 <= len(coins) <= 15):
        return False
    if not all(isinstance(c, int) and not isinstance(c, bool) and 1 <= c <= 25 for c in coins):
        return False
    if len(set(coins)) != len(coins):
        return False
    if not (1 <= k <= 2 * 10**9):
        return False
    return True

def ref(inp: str) -> str:
    coins, k = _parse(inp)
    # Literal definition: scan positive integers in order, count those
    # divisible by at least one coin, return the k-th such amount.
    count = 0
    x = 0
    while True:
        x += 1
        if any(x % c == 0 for c in coins):
            count += 1
            if count == k:
                return json.dumps(x)
